import type { Doc, Id, QueryCtx } from "@wizard/sdk";

type Status = Doc<"ticket">["status"];
type Scope = { stream: Id<"stream"> } | { ticket_type: Id<"ticket_type"> };

/** Неоплаченная бронь держит место 30 минут, затем место снова свободно. */
export const HOLD_MINUTES = 30;

/**
 * Занятые места в потоке или типе билета: оплаченные, выданные по квоте и свежие брони.
 * Считает по всем билетам, поэтому нужен systemDb; наружу отдаётся только число.
 */
export async function occupied(ctx: Pick<QueryCtx, "systemDb" | "now">, scope: Scope): Promise<number> {
  const since = new Date(ctx.now.getTime() - HOLD_MINUTES * 60_000).toISOString();
  const count = (status: Status, fresh = false) =>
    ctx.systemDb.ticket.count({ where: fresh ? { ...scope, status, created_at: { gte: since } } : { ...scope, status } });
  return (await count("paid")) + (await count("issued")) + (await count("pending_payment", true));
}

import { query } from "@wizard/sdk";

// Партнёр видит только свою квоту: ctx.db применяет rowFilter роли (partner_user = $user.id).
// Организатор с той же функцией видит все квоты — его permission без rowFilter.
export default query({
  args: {},
  handler: async (ctx) => {
    const quotas = await ctx.db.partner_quota.list({ limit: 100 });
    return quotas.map((q) => ({
      id: q.id,
      company: q.company,
      promoCode: q.promo_code,
      total: q.total,
      used: q.used,
      left: Math.max(q.total - q.used, 0),
    }));
  },
});

import { mutation, v } from "@wizard/sdk";
import { occupied } from "./lib/occupancy";

const EVENT_STARTS_AT = "2026-11-14T06:30:00.000Z"; // 14 ноября, 09:30 по Москве

// SERIALIZABLE-транзакция: при гонке runtime повторит handler, лимит не будет превышен.
// Участник не имеет права create на ticket, поэтому обойти лимит через data API нельзя;
// запись идёт через systemDb только после всех проверок.
export default mutation({
  args: {
    ticketTypeId: v.id("ticket_type"),
    streamId: v.id("stream"),
    holderName: v.string({ min: 2, max: 200 }),
    holderEmail: v.email(),
    holderPhone: v.optional(v.phone()),
    promoCode: v.optional(v.string({ max: 40 })),
  },
  handler: async (ctx, a) => {
    const userId = ctx.user.id;
    if (!userId) throw ctx.error("UNAUTHENTICATED", { message: "Войдите, чтобы оформить билет" });
    const type = await ctx.db.ticket_type.get(a.ticketTypeId);
    const stream = await ctx.db.stream.get(a.streamId);
    if (!type?.active || !stream) throw ctx.error("NOT_FOUND", { message: "Билет или поток не найден" });

    if ((await occupied(ctx, { stream: stream.id })) >= stream.capacity) {
      throw ctx.error("STREAM_FULL", { message: `В потоке «${stream.name}» не осталось мест` });
    }
    if ((await occupied(ctx, { ticket_type: type.id })) >= type.capacity) {
      throw ctx.error("SOLD_OUT", { message: `Билеты «${type.name}» закончились` });
    }

    let free = false;
    if (a.promoCode) {
      const quota = await ctx.systemDb.partner_quota.getBy("promo_code", a.promoCode.trim().toUpperCase());
      if (!quota || quota.ticket_type !== type.id) throw ctx.error("PROMO_INVALID", { message: "Промокод не подходит к этому билету" });
      if (quota.used >= quota.total) throw ctx.error("QUOTA_EXHAUSTED", { message: "Квота партнёра исчерпана" });
      await ctx.systemDb.partner_quota.patch(quota.id, { used: quota.used + 1 });
      free = true;
    } else if (type.kind === "partner") {
      throw ctx.error("PROMO_REQUIRED", { message: "Для партнёрского билета нужен промокод" });
    }

    const ticketId = await ctx.systemDb.ticket.insert({
      ticket_type: type.id,
      stream: stream.id,
      holder_user: userId,
      holder_name: a.holderName.trim(),
      holder_email: a.holderEmail,
      holder_phone: a.holderPhone ?? null,
      status: free ? "issued" : "pending_payment",
      amount: free ? 0 : type.price,
      promo_code: a.promoCode ?? null,
      event_starts_at: EVENT_STARTS_AT,
    });
    return { ticketId, needsPayment: !free };
  },
});

import { action, v } from "@wizard/sdk";

const fmt = new Intl.DateTimeFormat("ru-RU", {
  timeZone: "Europe/Moscow", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit",
});

// Запускается воркфлоу ticket_reminder за 24 часа до начала. Текст без ПДн:
// ни имени, ни телефона; chat_id по userId подставляет коннектор на стороне хоста.
export default action({
  args: { ticketId: v.id("ticket"), userId: v.id("users"), startsAt: v.datetime() },
  handler: async (ctx, { ticketId, userId, startsAt }) => {
    const res = await ctx.connectors.telegram.sendToUser({
      userId,
      text: `Напоминаем: форум «Северный ритейл» начнётся ${fmt.format(new Date(startsAt))}. Покажите QR-код билета на входе А.`,
      buttons: [{ text: "Открыть билет", url: `/ticket/${ticketId}` }],
      idempotencyKey: `reminder:${ticketId}`,
    });
    if (!res.delivered) ctx.log.info("reminder_skipped", { notLinked: res.reason === "not_linked" });
    return { delivered: res.delivered };
  },
});

import { query } from "@wizard/sdk";
import { occupied } from "./lib/occupancy";

// Публичная витрина билетов: цена и остаток мест, без данных владельцев.
export default query({
  args: {},
  handler: async (ctx) => {
    const types = await ctx.db.ticket_type.list({ where: { active: true }, limit: 20 });
    return Promise.all(
      types.map(async (t) => ({
        id: t.id,
        name: t.name,
        kind: t.kind,
        price: t.price,
        description: t.description,
        left: Math.max(t.capacity - (await occupied(ctx, { ticket_type: t.id })), 0),
      })),
    );
  },
});

import { type ClientDoc, type Id, useEntityList, useMutation, useNavigate, usePayment, useQuery, useState, useUser } from "@wizard/sdk";
import { AppShell, Badge, Button, Catalog, ConsentCheckbox, Field } from "@wizard/ui-kit";

type TicketType = ClientDoc<"ticket_type">;

export default function Landing() {
  const { user, login } = useUser();
  const availability = useQuery("ticketAvailability", {});
  const quota = useQuery("partnerQuota", user?.role === "partner" ? {} : "skip");
  const [picked, setPicked] = useState<Id<"ticket_type"> | null>(null);
  const left = new Map(availability.data?.map((t) => [t.id, t.left]));

  return (
    <AppShell>
      {quota.data?.map((q) => (
        <Badge key={q.id} tone="accent">{`Квота «${q.company}»: ${q.used} из ${q.total}, промокод ${q.promoCode}`}</Badge>
      ))}
      <Catalog
        entity="ticket_type"
        query={{ filter: { active: true }, sort: { field: "price", dir: "asc" } }}
        map={(t: TicketType) => ({
          id: t.id,
          title: t.name,
          description: t.description ?? undefined,
          price: t.kind === "partner" ? null : t.price,
          priceText: "по промокоду",
          remaining: left.get(t.id) ?? null,
        })}
        onSelect={(t: TicketType) => (user ? setPicked(t.id) : login({ role: "participant", next: "/" }))}
      />
      {picked && <RegisterForm ticketTypeId={picked} onCancel={() => setPicked(null)} />}
    </AppShell>
  );
}

// Форма без RecordForm: билет создаёт функция registerTicket (лимиты, промокод), а не data API.
// Согласие на ПДн: ConsentCheckbox (текст и ссылка на политику — из RoleSpec); SDK отправляет _consent через { consent: true }.
function RegisterForm({ ticketTypeId, onCancel }: { ticketTypeId: Id<"ticket_type">; onCancel: () => void }) {
  const streams = useEntityList("stream", { sort: "name" });
  const [register, reg] = useMutation("registerTicket");
  const payment = usePayment("yookassa");
  const navigate = useNavigate();
  const [form, setForm] = useState({ streamId: "", holderName: "", holderEmail: "", promoCode: "", consent: false });
  const set = (k: keyof typeof form) => (v: unknown) => setForm({ ...form, [k]: v });

  const submit = async () => {
    const res = await register(
      {
        ticketTypeId,
        streamId: form.streamId as Id<"stream">,
        holderName: form.holderName,
        holderEmail: form.holderEmail,
        promoCode: form.promoCode || undefined,
      },
      { consent: true },
    );
    if (res.needsPayment) await payment.pay("ticket", res.ticketId);
    else navigate(`/ticket/${res.ticketId}`);
  };

  return (
    <form onSubmit={(e) => { e.preventDefault(); if (form.consent) void submit(); }}>
      <Field name="streamId" label="Поток" type="enum" required value={form.streamId} onChange={set("streamId")}
        enumOptions={streams.items.map((s) => ({ value: s.id, label: s.name }))} />
      <Field name="holderName" label="ФИО" type="string" required value={form.holderName} onChange={set("holderName")} />
      <Field name="holderEmail" label="Email" type="email" required value={form.holderEmail} onChange={set("holderEmail")} />
      <Field name="promoCode" label="Промокод партнёра" type="string" value={form.promoCode} onChange={set("promoCode")} />
      <ConsentCheckbox checked={form.consent} onChange={set("consent")} />
      {reg.error && <Badge tone="bad">{reg.error.details.message ?? "Не удалось оформить билет"}</Badge>}
      <Button type="submit" variant="primary" loading={reg.pending || payment.pending} disabled={!form.consent}>Оформить</Button>
      <Button variant="ghost" onClick={onCancel}>Отмена</Button>
    </form>
  );
}

import { type ClientDoc, useState } from "@wizard/sdk";
import { Button, CabinetLayout, DataTable, RecordCard } from "@wizard/ui-kit";

type Application = ClientDoc<"speaker_application">;
type Status = Application["status"];

const SECTIONS: { id: Status; label: string }[] = [
  { id: "new", label: "Новые" },
  { id: "approved", label: "Одобренные" },
  { id: "rejected", label: "Отклонённые" },
];

// Телефон спикера скрыт от модератора правами (hiddenFields) — ни колонки, ни поля в карточке.
// Решение модератора — патч статуса; письмо и Telegram отправляет воркфлоу speaker_approved.
export default function Moderation() {
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const table = (status: Status) => (
    <DataTable
      entity="speaker_application"
      columns={["topic", "company", "stream", "created_at"]}
      query={{ filter: { status } }}
      defaultSort={{ field: "created_at", dir: "desc" }}
      filters={["stream"]}
      searchable
      onRowClick={(row: Application) => setSelectedId(row.id)}
      emptyText="Заявок нет"
    />
  );

  const detail = selectedId && (
    <>
      <RecordCard
        entity="speaker_application"
        id={selectedId}
        fields={["full_name", "company", "topic", "abstract", "stream", "status", "moderator_comment"]}
        title={(r: Application) => r.topic}
        actions={[
          { id: "approve", label: "Одобрить", tone: "primary", kind: "update", patch: { status: "approved" }, visible: (r: Application) => r.status === "new" },
          { id: "reject", label: "Отклонить", tone: "danger", kind: "update", patch: { status: "rejected" }, confirm: "Отклонить заявку?", visible: (r: Application) => r.status === "new" },
        ]}
      />
      <Button variant="ghost" onClick={() => setSelectedId(null)}>Закрыть</Button>
    </>
  );

  return (
    <CabinetLayout
      title="Модерация заявок"
      defaultSection="new"
      sections={SECTIONS.map((s) => ({ id: s.id, label: s.label, content: <>{table(s.id)}{detail}</> }))}
    />
  );
}

import { useEntity, useParams } from "@wizard/sdk";
import { AppShell, Badge, QrTicket } from "@wizard/ui-kit";

export default function MyTicket() {
  const { id } = useParams<{ id: string }>();
  const { data: ticket, isLoading } = useEntity("ticket", id);
  const valid = ticket?.status === "paid" || ticket?.status === "issued";

  return (
    <AppShell title="Мой билет">
      {valid ? (
        <QrTicket
          entity="ticket"
          id={id}
          tokenField="qr_token"
          title="Форум «Северный ритейл»"
          subtitle="14 ноября · 09:30 · Казань"
          hint="Покажите QR на входе А · работает без интернета"
        />
      ) : (
        <Badge tone="warn">{isLoading ? "Загружаем билет…" : "Билет ещё не оплачен"}</Badge>
      )}
    </AppShell>
  );
}

import { AppShell, QrScanner } from "@wizard/ui-kit";

// Проверка — служебный /_wizard/qr/check; офлайн-манифест, очередь и синхронизация — в компоненте (M2, connectors/qr.yaml).
export default function Scanner() {
  return (
    <AppShell title="Сканер билетов">
      <QrScanner checkpoint="Вход А" offline />
    </AppShell>
  );
}
